// Generates src/system.ts: the embedded surface has no helper functions, so the per-task branches are written out here.
import { writeFileSync, mkdirSync } from 'node:fs';

const TASKS = [0, 1, 2];
const INFLIGHT = '[$.queued, $.running, $.evicted]';

// The run's status after task `i` takes the value `y` (an expression), the other tasks unchanged.
function derive(i, y) {
  const [a, b] = TASKS.filter((j) => j !== i).map((j) => `$.task${j}`);
  return `when(${y} === ${a} && ${a} === ${b}, [set('status', ${y})], [
            when(${y} === $.failed || ${a} === $.failed || ${b} === $.failed, [set('status', $.failed)], [
              when(isIn(${y}, ${INFLIGHT}) || isIn(${a}, ${INFLIGHT}) || isIn(${b}, ${INFLIGHT}), [set('status', $.running)], [set('status', $.cancelled)]),
            ]),
          ])`;
}

// A task move: from `from` to `to`, refused with `reason` otherwise.
function move(actionName, from, to, reason) {
  const branches = TASKS.map((i) => `        when($.task === ${i}, [
          require($.task${i} === $.${from}, '${reason}'),
          set('task${i}', $.${to}),
          ${derive(i, `$.${to}`)},
        ]),`).join('\n');
  return `      on('${actionName}', ($) => [
        require($.started, 'not-started'),
${branches}
      ], ['task']),`;
}

const src = `// Workflow run status (T5). Generated by gen/make-system.mjs; edit that and rerun it.
import { module, enumType, machine, field, t, action, on, require, set, when, terminal, invariant, implies, isIn } from '@cognitive-fab/poly/embed';

export default module('workflow', [
  enumType('Status', ['queued', 'running', 'evicted', 'completed', 'failed', 'cancelled']),
  machine('Run', {
    state: {
      status: field(t.named('Status'), ($) => $.queued),
      task0: field(t.named('Status'), ($) => $.queued),
      task1: field(t.named('Status'), ($) => $.queued),
      task2: field(t.named('Status'), ($) => $.queued),
      started: field(t.bool, () => false),
    },
    items: [
      terminal(($) => isIn($.status, [$.completed, $.failed, $.cancelled])),
      action('Start', {}),
      action('TaskStarted', { task: t.int.check(0, 2, 'strict') }),
      action('TaskCompleted', { task: t.int.check(0, 2, 'strict') }),
      action('TaskFailed', { task: t.int.check(0, 2, 'strict') }),
      action('TaskEvicted', { task: t.int.check(0, 2, 'strict') }),
      action('TaskRequeued', { task: t.int.check(0, 2, 'strict') }),
      action('Cancel', {}),
      on('Start', ($) => [require(!$.started, 'run-exists'), set('started', true)]),
${move('TaskStarted', 'queued', 'running', 'task-not-queued')}
${move('TaskCompleted', 'running', 'completed', 'task-not-running')}
${move('TaskFailed', 'running', 'failed', 'task-not-running')}
${move('TaskEvicted', 'running', 'evicted', 'task-not-running')}
${move('TaskRequeued', 'evicted', 'queued', 'task-not-evicted')}
      on('Cancel', ($) => [
        require($.started, 'not-started'),
        require(${TASKS.map((i) => `isIn($.task${i}, ${INFLIGHT})`).join(' || ')}, 'nothing-in-flight'),
${TASKS.map((i) => `        when(isIn($.task${i}, ${INFLIGHT}), [set('task${i}', $.cancelled)]),`).join('\n')}
        when($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
      ]),
      invariant('completed-only-when-all-completed', ($) =>
        implies($.status === $.completed, $.task0 === $.completed && $.task1 === $.completed && $.task2 === $.completed)),
      invariant('failed-whenever-a-task-failed', ($) =>
        implies($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, $.status === $.failed)),
      invariant('not-final-while-in-flight', ($) =>
        implies(${TASKS.map((i) => `isIn($.task${i}, ${INFLIGHT})`).join(' || ')}, !isIn($.status, [$.completed, $.cancelled]))),
    ],
  }),
]);
`;
mkdirSync(new URL('../src/', import.meta.url), { recursive: true });
writeFileSync(new URL('../src/system.ts', import.meta.url), src);
console.log('wrote src/system.ts');

