npm run adapter 2>&1 | tail -5; mkdir -p test; cat > test/host.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };
const view = (status, t0, t1, t2) => ({ status, task0: t0, task1: t1, task2: t2 });

test('start, unknown runs, duplicates', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.deepEqual(await h.run('a'), view('queued', 'queued', 'queued', 'queued'));
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), view('queued', 'queued', 'queued', 'queued'));
});

test('bad task numbers and illegal moves are refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [3, -1, 1.5]) assert.equal((await h.taskStarted('r', t)).ok, false, String(t));
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.deepEqual(await h.taskStarted('r', 1), ok);
  assert.equal((await h.taskStarted('r', 1)).ok, false);
  assert.deepEqual(await h.run('r'), view('running', 'queued', 'running', 'queued'));
});

test('completed only when all complete', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { assert.deepEqual(await h.taskStarted('r', t), ok); }
  assert.deepEqual(await h.run('r'), view('running', 'running', 'running', 'running'));
  await h.taskCompleted('r', 0); await h.taskCompleted('r', 1);
  assert.equal((await h.run('r')).status, 'running');
  await h.taskCompleted('r', 2);
  assert.deepEqual(await h.run('r'), view('completed', 'completed', 'completed', 'completed'));
  assert.equal((await h.cancel('r')).ok, false);
});

test('evicted counts as in flight; all evicted is evicted; requeue', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  await h.taskCompleted('r', 0); await h.taskCompleted('r', 1);
  await h.taskEvicted('r', 2);
  assert.deepEqual(await h.run('r'), view('running', 'completed', 'completed', 'evicted'));
  await h.taskRequeued('r', 2);
  assert.deepEqual(await h.run('r'), view('running', 'completed', 'completed', 'queued'));
  const g = await createHost();
  await g.start('x');
  for (const t of [0, 1, 2]) await g.taskStarted('x', t);
  for (const t of [0, 1, 2]) await g.taskEvicted('x', t);
  assert.equal((await g.run('x')).status, 'evicted');
  for (const t of [0, 1, 2]) await g.taskRequeued('x', t);
  assert.equal((await g.run('x')).status, 'queued');
});

test('failure ends the run', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  assert.deepEqual(await h.taskFailed('r', 0), ok);
  assert.deepEqual(await h.run('r'), view('failed', 'failed', 'queued', 'queued'));
  assert.equal((await h.taskStarted('r', 1)).ok, false);
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0); await h.taskCompleted('r', 0);
  await h.taskStarted('r', 1); await h.taskEvicted('r', 1);
