// Generates src/system.ts: the embedded surface has no helper functions, so the per-task branches are written out here.
import { writeFileSync, mkdirSync } from 'node:fs';

const TASKS = [0, 1, 2];
const INFLIGHT = '[$.queued, $.running, $.evicted]';

// The run's status after task `i` takes the value `y` (an expression), the other tasks unchanged.
function derive(i, y) {
  const [a, b] = TASKS.filter((j) => j !== i).map((j) => `$.task${j}`);
  return `when(${y} === ${a} && ${a} === ${b}, [set('status', ${y})], [
            when(${y} === $.failed || ${a} === $.failed || ${b} === $.failed, [set('status', $.failed)], [
              when(isIn(${y}, ${INFLIGHT}) || isIn(${a}, ${INFLIGHT}) || isIn(${b}, ${INFLIGHT}), [set('status', $.running)], [set('status', $.cancelled)]),
            ]),
          ])`;
}

// A task move: from `from` to `to`, refused with `reason` otherwise.
function move(actionName, from, to, reason) {
  const body = (i) => `[
          require($.task${i} === $.${from}, '${reason}'),
          set('task${i}', $.${to}),
          ${derive(i, `$.${to}`)},
        ]`;
  // if task 0 … else if task 1 … else (task 2, the strict domain being 0..2).
  return `      on('${actionName}', ($) => [
        require($.started, 'not-started'),
        when($.task === 0, ${body(0)}, [when($.task === 1, ${body(1)}, ${body(2)})]),
      ], ['task']),`;
}

